<template><div><div class="flex justify-between items-center"><div><p class="text-sm" style="color:var(--muted)">Dashboard</p><h1 class="text-3xl font-semibold">内容总览</h1></div><NuxtLink to="/admin/posts/new" class="rounded-full px-5 py-2 text-white" style="background:var(--accent)">写文章</NuxtLink></div><div class="mt-10 grid grid-cols-2 lg:grid-cols-4 gap-4"><div v-for="c in cards" :key="c[0]" class="rounded-xl border p-5" style="border-color:var(--border);background:var(--surface)"><p class="text-sm" style="color:var(--muted)">{{c[0]}}</p><p class="mt-2 text-3xl font-semibold">{{c[1]??'—'}}</p></div></div><div class="mt-10 grid lg:grid-cols-2 gap-8"><section><h2 class="font-semibold">最近编辑</h2><NuxtLink v-for="p in data?.recent||[]" :key="p.id" :to="`/admin/posts/${p.id}`" class="mt-3 flex justify-between border-b py-3" style="border-color:var(--border)"><span>{{p.title}}</span><small>{{p.status}}</small></NuxtLink></section><section><h2 class="font-semibold">热门文章</h2><div v-for="p in data?.popular||[]" :key="p.id" class="mt-3 flex justify-between border-b py-3" style="border-color:var(--border)"><span>{{p.title}}</span><small>{{p.views}} 浏览</small></div></section></div></div></template>
